import AppKit
import FudehandCore

/// The icon shown beside each Agent in the "MCP Connectors" window and each provider in the model settings. The marks are the vendors' own
/// (Claude, Codex, DeepSeek, OpenAI), taken
/// unchanged from lobehub/icons (`@lobehub/icons-static-svg` 1.103.0, MIT): only the `width`/`height`/`style`/`title` attributes were
/// replaced with a 24 × 24 size, and arc commands were written with spaces between their flags (`0 0 1` instead of `001`), which the
/// system SVG renderer needs. They are kept in source so the App draws them without a resource bundle.
enum ConnectorIcon {
    @MainActor private static var cache: [AgentConnector: NSImage] = [:]

    @MainActor static func image(for connector: AgentConnector) -> NSImage? {
        if let image = cache[connector] { return image }
        let image = NSImage(data: Data(svg(connector).utf8))
        cache[connector] = image
        return image
    }

    /// The icon for a chat provider id in the model settings ("deepseek", "anthropic", "openai"); nil for an unknown id. The OpenAI mark is
    /// one color, so it is a template image that takes the row's text color (black, white in dark appearance or on a selected row).
    @MainActor static func image(forProvider id: String) -> NSImage? {
        switch id {
        case "deepseek": image(for: .deepseek)
        case "anthropic": image(for: .claude)
        case "openai": openAIImage
        default: nil
        }
    }

    @MainActor private static let openAIImage: NSImage? = {
        let image = NSImage(data: Data(openai.utf8))
        image?.isTemplate = true
        return image
    }()

    private static func svg(_ connector: AgentConnector) -> String {
        switch connector {
        case .claude: claude
        case .codex: codex
        case .deepseek: deepseek
        }
    }

